import{_ as a,o as t,c as r,a8 as i,ao as l,ap as n,aq as o}from"./chunks/framework.ALLMRHJF.js";const g=JSON.parse('{"title":"BreadCrumb Block","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-plugin/user/breadcrumb-block.md","filePath":"content/plugins/bcew-plugin/user/breadcrumb-block.md"}'),s={name:"content/plugins/bcew-plugin/user/breadcrumb-block.md"};function c(h,e,d,p,b,m){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="breadcrumb-block" tabindex="-1">BreadCrumb Block <a class="header-anchor" href="#breadcrumb-block" aria-label="Permalink to “BreadCrumb Block”">​</a></h1><p>The BreadCrumb Block outputs a trail representing the current view (for example, Home / Parent / Child). It is especially useful for large sites with nested pages.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to “When to use”">​</a></h2><p>Place the block near the top of templates or in a Header/Content template part to improve navigation clarity and orientation.</p><p><img src="'+l+'" alt="Using Breadcrumbs"></p><h2 id="editing-experience" tabindex="-1">Editing experience <a class="header-anchor" href="#editing-experience" aria-label="Permalink to “Editing experience”">​</a></h2><p>In the Site Editor or content editor, the block shows the static example Home / Parent / Child. The current context and hierarchy appear only on the front end. The block has no breadcrumb-specific settings.</p><p><img src="'+n+'" alt="Add a Breadcrumb Block"></p><h2 id="front-end-behavior" tabindex="-1">Front-end behavior <a class="header-anchor" href="#front-end-behavior" aria-label="Permalink to “Front-end behavior”">​</a></h2><p>For singular hierarchical content, the trail contains Home, intermediate ancestors, and the current item as plain text. For non-hierarchical singular content, the posts index, search results, archives, and 404 pages, it shows Home followed by the current context. Home and ancestors are links; the current item is not linked. The breadcrumb is not displayed on the front page.</p><h2 id="usage-examples" tabindex="-1">Usage examples <a class="header-anchor" href="#usage-examples" aria-label="Permalink to “Usage examples”">​</a></h2><h3 id="add-to-a-template" tabindex="-1">Add to a template <a class="header-anchor" href="#add-to-a-template" aria-label="Permalink to “Add to a template”">​</a></h3><ol><li>Appearance &gt; Editor.</li><li>Open the relevant template or create a Template Part such as Header.</li><li>Insert “BreadCrumb” block below site header.</li><li>Save and view the template on the front end.</li></ol><h3 id="quick-demo-hierarchy" tabindex="-1">Quick demo hierarchy <a class="header-anchor" href="#quick-demo-hierarchy" aria-label="Permalink to “Quick demo hierarchy”">​</a></h3><p>Create three Pages:</p><ul><li>Grandparent (top level)</li><li>Parent (set Parent to Grandparent)</li><li>Child (set Parent to Parent)</li></ul><p>View the Child page with the block placed in the Page template.</p><p><img src="'+o+'" alt="Page Hierarchy"></p><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to “Accessibility”">​</a></h2><ul><li>Uses a navigation landmark with an accessible label.</li><li>Each ancestor is a link; the current item is plain text.</li><li>Keep link text concise; page title changes automatically propagate.</li></ul><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best practices”">​</a></h2><ul><li>Avoid placing multiple breadcrumb blocks on the same template.</li><li>Keep divider style consistent site-wide.</li><li>Do not manually duplicate breadcrumb links in body content.</li></ul><h2 id="breadcrumb-troubleshooting" tabindex="-1">Breadcrumb troubleshooting <a class="header-anchor" href="#breadcrumb-troubleshooting" aria-label="Permalink to “Breadcrumb troubleshooting”">​</a></h2><ul><li>Breadcrumbs missing: Confirm the block is present in the template used by the current view.</li><li>Wrong hierarchy: Verify parent settings for each Page.</li><li>Breadcrumb absent on the front page: This is expected behavior.</li></ul><p>Archives show the current archive title but not a taxonomy ancestor path.</p>',25)])])}const k=a(s,[["render",c]]);export{g as __pageData,k as default};
